def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0 if v == 3 else v for v in row] for row in grid]

    # Locate each separate 2-object and mark its extreme corner cell.
    seen = set()
    for r in range(h):
        for c in range(w):
            if out[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                x, y = stack.pop()
                comp.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and out[nx][ny] == 2 and (nx,ny) not in seen:
                        seen.add((nx,ny))
                        stack.append((nx,ny))
            # Mark the uppermost occupied cell, breaking ties toward the
            # outside (left for upper figures, right for lower figures).
            top = min(x for x, y in comp)
            candidates = [(x, y) for x, y in comp if x == top]
            if top < h // 2:
                rr, cc = min(candidates, key=lambda p: p[1])
            else:
                rr, cc = max(candidates, key=lambda p: p[1])
            out[rr][cc] = 8
    return out
